import React from "react";
import { useUsers } from "../hooks/useUsers";
import { neonColors } from "../constants/color";

const Users = () => {
  const { users, active, setActive } = useUsers();
  return (
    <div style={{ flexDirection: "row", display: "flex" }}>
      {users.map((item, index) => {
        const color = neonColors[index];
        const indexValue = active?.match(index.toString());
        return (
          <div
            style={{
              display: "flex",
              borderRadius: "50%",
              backgroundColor: indexValue? color: "transparent",
              borderWidth: indexValue ? 4 : 2,
              borderStyle: "solid",
              borderColor: color,
              height: 44,
              width: 44,
              boxSizing: "border-box",
              alignItems: "center",
              justifyContent: "center",
              marginRight: 10,
              color: color,
              fontWeight: indexValue ? "bold" : "500",
            }}
            onClick={() => setActive(index.toString())}
          >
            {item?.name.charAt(0)}
          </div>
        );
      })}
    </div>
  );
};

export default React.memo(Users);
